pragma solidity >=0.8.0;
contract CryptoPackedProbe {
    bytes32 hEncoded;

    event Hashes(bytes32 packedH, bytes32 encodedH, bytes32 shaH);

    function compute(uint8 x, string memory s, bytes memory b) external {
        bytes32 p = keccak256(abi.encodePacked(x, s, b));
        hEncoded = keccak256(abi.encode(x, s, b));
        emit Hashes(p, hEncoded, sha256(abi.encodePacked(x, s, b)));
    }

    function getEncoded() external view returns (bytes32) { return hEncoded; }
}
